import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"7、【師】 坎下坤上","description":"周易口訣義 - 7、【師】 坎下坤上","frontmatter":{"title":"7、【師】 坎下坤上","description":"周易口訣義 - 7、【師】 坎下坤上"},"headers":[],"relativePath":"classics/koujueyi/009.md","filePath":"classics/koujueyi/009.md"}'),r={name:"classics/koujueyi/009.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_7、【師】-坎下坤上" tabindex="-1">7、【師】 坎下坤上 <a class="header-anchor" href="#_7、【師】-坎下坤上" aria-label="Permalink to “7、【師】 坎下坤上”">​</a></h1><p>彖曰：師，眾也；貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下而民從之，吉又何咎矣！</p><p>象曰：地中有水，「師」，君子以容民畜眾。</p><p>初六：師出以律，否臧兇。</p><p>象曰：「師出以律」，失律兇也。</p><p>九二：在師中吉，無咎。王三錫命。</p><p>象曰：「在師中吉」，承天寵也。「王三錫命」，懷萬邦也。</p><p>六三：師或輿尸，兇。</p><p>象曰：「師或輿尸」，大無功也。</p><p>六四：師左次，無咎。</p><p>象曰：「左次無咎」，未失常也。</p><p>六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇。</p><p>象曰：「長子帥師」，以中行也。「弟子輿尸」，使不當也。</p><p>上六：大君有命，開國承家，小人勿用。</p><p>象曰：「大君有命」，以正功也。「小人勿用」，必亂邦也。</p><p>解讀</p><p>「師貞丈人吉無咎」者，師者，眾也，軍旅之名，法長之義，故陸績雲「師為眾首，法長而行」是也。以師為正，故曰</p><p>「師」。貞丈人吉無咎者，丈人謂嚴毅德長之人，可以監臨於眾，故曰「丈人」也。夫興師征伐，必須有功勞，即無罪咎，故曰「吉，無咎」也。</p><p>象曰「地中有水，師，君子以容民畜眾」者，緣地能包水，亦猶為師之主，容納於民也。君子為眾之長，當含小過，不尚絕嚴，容納民人，畜聚於眾也。</p><p>「初六，師出以律，否臧，兇」者，律，法也；否，破敗也；臧，有功也。初六為師之首，必須齊整師旅，而不失法律者也。若其失律違法，雖見獲功，徒勞而已，故否之與臧，皆見兇也。</p><p>九二，在師中，吉，無咎。「王三錫命」者，九二以剛德處中，為君委任，故曰「在師中」也。既為君所任，任大役重，必須有功，無功即兇，故曰「吉，無咎」也。吉者，有功之辭也。「王三錫命」者，以其能招萬邦而有功，故君王三度錫賜其命。</p><p>「六三，師或輿尸，兇」者，六三體質柔弱，而復乘剛，又無應援，若使之行師，必見喪敗，故曰輿尸而歸，「兇」也。</p><p>「六四，師左次，無咎」者，以陰得位而無其應，無應即不可征伐也，得位則可以自處也。夫為帥眾而處，必須量其便宜，取其右背山陵，前左水澤，而次止之，則「無咎」也。又云：「左是偏將處之，右是上將，有主死之權也。</p><p>六五：田有禽，利執言，無咎。長子帥師，弟子輿尸，貞兇」者，以柔處尊，不先威猛，只是物來先犯者也。猶如田之苗稼為禽所犯，故用執之言語，問其情誅，亦無咎。故曰：「田有禽，利執言，無咎。」六五體既柔弱，不可自行攻伐，故任用長子帥領師眾也。若任之弟子，則致「輿尸」之兇。故莊氏雲：「長子謂九二，德長於人也；弟子謂六三，德劣於物也。」</p><p>「上六：大君有命，開國承家，小人勿用」者，上六處師之極，即是有功之人。既有功勞，即天子錫之爵命矣。若其功大，開國為諸侯；若其功小，使之承家為卿大夫也。若山入有功，但錫之金帛，不可任之以位，故勿用小人，必亂邦也。「大君」為天子，亦喻大人有天命，用之開國。小人無命，止於為盜。</p>',25)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
